mapper.select:
SELECT COUNT(*) FROM (
  SELECT c.id  GROUP BY c.id
) candidate_count

SELECT  FROM crm_followup_batch
WHERE tenant_id=#{tenantId}
  AND ((status='FAILED' AND next_retry_at IS NOT NULL AND next_retry_at<=#{now})
    OR (status='RUNNING' AND lease_expires_at IS NOT NULL AND lease_expires_at<=#{now}))
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE crm_followup_batch
SET status=#{status},retry_count=retry_count+#{failureIncrement},next_retry_at=#{nextRetryAt},
    lease_owner=NULL,lease_expires_at=NULL,last_error_masked=#{errorMasked},finished_at=#{finishedAt},
    version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND status='RUNNING' AND lease_owner=#{leaseOwner}

mapper.select:
SELECT  FROM crm_followup_batch_item i
INNER JOIN crm_customer c ON c.tenant_id=i.tenant_id AND c.id=i.customer_id
WHERE i.tenant_id=#{tenantId} AND i.batch_id=#{batchId} AND i.customer_id=#{customerId}

SELECT DISTINCT t.tenant_id FROM crm_task t
WHERE t.status IN ('OPEN','PROCESSING') AND t.source_type IN ('FOLLOWUP','MONTHLY_BATCH')
  AND t.assignee_user_id IS NOT NULL AND t.due_at IS NOT NULL AND t.due_at<=#{now}

SELECT t.id,t.tenant_id AS tenantId,t.customer_id AS customerId,t.assignee_user_id AS assigneeUserId,t.due_at AS dueAt
FROM crm_task t
WHERE t.tenant_id=#{tenantId} AND t.status IN ('OPEN','PROCESSING') AND t.source_type IN ('FOLLOWUP','MONTHLY_BATCH')
  AND t.assignee_user_id IS NOT NULL AND t.due_at IS NOT NULL AND t.due_at<=#{now}

ORDER BY t.id LIMIT #{limit}

